static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    int startDayOfMonth = ((dayOfMonth - 1) / dayStep) * dayStep + 1;

    return year * 10000 + month * 100 + startDayOfMonth;
}

long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    // Calculate the start day of the month
    LocalDate firstDayOfMonth = LocalDate.of(year, month, 1);
    int firstDayOfWeek = firstDayOfMonth.getDayOfWeek().getValue(); // Monday is 1, Sunday is 7

    // Calculate the day of the week for the given dayOfMonth
    LocalDate givenDate = LocalDate.of(year, month, dayOfMonth);
    int dayOfWeek = givenDate.getDayOfWeek().getValue();

    // Calculate the number of days to subtract to get to the nearest previous dayStep day
    int daysToSubtract = (dayOfWeek - firstDayOfWeek + 7) % 7;
    if (daysToSubtract > dayStep) {
        daysToSubtract -= 7;
    }
    int newDayOfMonth = dayOfMonth - daysToSubtract;

    // Adjust if newDayOfMonth is less than or equal to 0
    if (newDayOfMonth <= 0) {
        newDayOfMonth += givenDate.minusMonths(1).lengthOfMonth();
    }

    return year * 10000L + month * 100L + newDayOfMonth;
}

