public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb = ensureCapacity(session, lb, 1);
            lb.buffer[lb.offset++] = (byte) c;
        } else if (c < 0x800) {
            lb = ensureCapacity(session, lb, 2);
            lb.buffer[lb.offset++] = (byte) (0xc0 | (c >> 6));
            lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3f));
        } else if (Character.isSurrogate(c)) {
            if (i + 1 >= len) throw new UTFDataFormatException("Invalid UTF-32 sequence in string: " + str);
            char low = str.charAt(++i);
            if (!Character.isSurrogatePair(c, low)) throw new UTFDataFormatException("Invalid UTF-32 surrogate pair in string: " + str);
            int codePoint = Character.toCodePoint(c, low);
            lb = ensureCapacity(session, lb, 4);
            lb.buffer[lb.offset++] = (byte) (0xf0 | (codePoint >> 18));
            lb.buffer[lb.offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
            lb.buffer[lb.offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
            lb.buffer[lb.offset++] = (byte) (0x80 | (codePoint & 0x3f));
        } else {
            lb = ensureCapacity(session, lb, 3);
            lb.buffer[lb.offset++] = (byte) (0xe0 | (c >> 12));
            lb.buffer[lb.offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3f));
        }
    }
    return lb;
}

LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            lb = writeByte((byte) c, lb);
        } else if (c <= 0x7FF) {
            lb = writeByte((byte) (0xC0 | (c >> 6)), lb);
            lb = writeByte((byte) (0x80 | (c & 0x3F)), lb);
        } else if (Character.isSurrogate(c)) {
            int cp = Character.toCodePoint(c, str.charAt(++i));
            lb = writeByte((byte) (0xF0 | (cp >> 18)), lb);
            lb = writeByte((byte) (0x80 | ((cp >> 12) & 0x3F)), lb);
            lb = writeByte((byte) (0x80 | ((cp >> 6) & 0x3F)), lb);
            lb = writeByte((byte) (0x80 | (cp & 0x3F)), lb);
        } else {
            lb = writeByte((byte) (0xE0 | (c >> 12)), lb);
            lb = writeByte((byte) (0x80 | ((c >> 6) & 0x3F)), lb);
            lb = writeByte((byte) (0x80 | (c & 0x3F)), lb);
        }
    }
    return lb;
}

