List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return Collections.emptyList();
    }
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }
    PathSegmentImpl.Fragmenter fragmenter = new PathSegmentImpl.Fragmenter(path);
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    while (fragmenter.hasNext()) {
        String segment = fragmenter.next();
        if (decode) {
            try {
                segment = URLDecoder.decode(segment, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is always supported, so ignore
            }
        }
        pathSegments.add(new PathSegmentImpl(segment));
    }
    return pathSegments;
}

