String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (++i >= len) throw new Exception("Invalid string escape sequence");
            c = str.charAt(i);
            switch (c) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    char hexChar1 = str.charAt(++i);
                    char hexChar2 = str.charAt(++i);
                    char hexChar3 = str.charAt(++i);
                    char hexChar4 = str.charAt(++i);
                    int value = Character.digit(hexChar1, 16) << 12 |
                                Character.digit(hexChar2, 16) << 8 |
                                Character.digit(hexChar3, 16) << 4 |
                                Character.digit(hexChar4, 16);
                    sb.append((char) value);
                    break;
                default:
                    throw new Exception("Invalid escape character: \\" + c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

