        if ((currentByte & 0x80) == 0) {
            // 1-byte format: 0xxxxxxx
            charBuffer[charOffset++] = (char) currentByte;
        } else if ((currentByte & 0xE0) == 0xC0) {
            // 2-byte format: 110xxxxx 10xxxxxx
            int charValue = (currentByte & 0x1F) << 6;
            currentByte = this.classFileBuffer[utf8Offset++] & 0xFF;
            charValue |= (currentByte & 0x3F);
            charBuffer[charOffset++] = (char) charValue;
