            currentByte = this.classFileBuffer[utf8Offset++] & 0xFF;
            charValue |= (currentByte & 0x3F) << 6;
            currentByte = this.classFileBuffer[utf8Offset++] & 0xFF;
            charValue |= (currentByte & 0x3F);
            charBuffer[charOffset++] = (char) charValue;
        }
    }
    return new String(charBuffer, 0, charOffset);
