private String unescapeId(String input){
    if (input == null) return null;
    StringBuilder output = new StringBuilder();
    boolean escapeMode = false;
    for (char c : input.toCharArray()) {
        if (escapeMode) {
            if (c == 'u') {
                // Handle Unicode escape sequence \uXXXX
                StringBuilder hex = new StringBuilder();
                for (int i = 0; i < 4; i++) {
                    hex.append(input.charAt(input.indexOf(c) + i + 1));
                }
                output.append((char) Integer.parseInt(hex.toString(), 16));
                escapeMode = false;
                c = input.charAt(input.indexOf(c) + 4); // Move the index past the Unicode escape
            } else {
                output.append(c);
                escapeMode = false;
            }
        } else if (c == '\\') {
            escapeMode = true;
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

