private String parseToken(final char[] terminators){
    StringBuilder token = new StringBuilder();
    int currentChar;
    while ((currentChar = this.content.get()) != -1) {
        char ch = (char) currentChar;
        boolean isTerminator = false;
        for (char terminator : terminators) {
            if (ch == terminator) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            this.content.position(this.content.position() - 1); // Rewind one character
            break;
        }
        token.append(ch);
    }
    return token.toString();
}

